// Hand-written source files stay under 500 lines. Tests (a test or tests folder) and generated files, which say so
// on their first line, are exempt.
import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const MAX = 500;
const SOURCE = /\.(js|mjs|cjs|ts|mts|svelte|css|dart)$/;
const SKIP = new Set([
  'node_modules',
  'test',
  'tests',
  'dist',
  'build',
  '.svelte-kit',
  '.dart_tool',
  '.git',
  'test-results',
  'playwright-report',
  // the work copies of the agents that build this repository
  '.claude',
]);

function files(dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    if (SKIP.has(entry.name)) return [];
    const path = join(dir, entry.name);
    if (entry.isDirectory()) return files(path);
    return SOURCE.test(entry.name) ? [path] : [];
  });
}

/** The hand-written source files over the limit, as "path: n lines". */
export function checkLines(root = ROOT, max = MAX) {
  return files(root).flatMap((path) => {
    const lines = readFileSync(path, 'utf8').split('\n');
    if (lines[0]?.includes('Generated by')) return [];
    const count = lines.at(-1) === '' ? lines.length - 1 : lines.length;
    return count > max ? [`${relative(root, path)}: ${count} lines, more than ${max}.`] : [];
  });
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const errors = checkLines();
  if (errors.length) {
    console.error(errors.map((e) => `✗ ${e}`).join('\n'));
    process.exit(1);
  }
  console.log(`✓ every hand-written source file has at most ${MAX} lines`);
}
